    // readUvarint is a type-specialized copy of encoding/binary.ReadUvarint.
    // This avoids the interface conversion and thus has better escape properties,
    // which flows up the stack.
    std::tuple<uint64_t, gocpp::error> readUvarint(strings::Reader* r)
    {
        uint64_t x = {};
        unsigned int s = {};
        for(auto i = 0; i < binary::MaxVarintLen64; i++)
        {
            auto [b, err] = rec::ReadByte(gocpp::recv(r));
            if(err != nullptr)
            {
                if(i > 0 && err == io::go_EOF)
                {
                    err = io::ErrUnexpectedEOF;
                }
                return {x, err};
            }
            if(b < 0x80)
            {
                if(i == binary::MaxVarintLen64 - 1 && b > 1)
                {
                    return {x, overflow};
                }
                return {x | (uint64_t(b) << s), nullptr};
            }
            x |= uint64_t(b & 0x7f) << s;
            s += 7;
        }
        return {x, overflow};
    }

    gocpp::error overflow = errors::New("pkgbits: readUvarint overflows a 64-bit integer"_s);
    int64_t rec::rawVarint(Decoder* r)
    {
        auto ux = rec::rawUvarint(gocpp::recv(r));

        // Zig-zag decode.
        auto x = int64_t(ux >> 1);
        if(ux & 1 != 0)
        {
            x = ~ x;
        }
        return x;
    }

