    // Sync decodes a sync marker from the element bitstream and asserts
    // that it matches the expected marker.
    //
    // If r.common.sync is false, then Sync is a no-op.
    void rec::Sync(Decoder* r, SyncMarker mWant)
    {
        if(! r->common->sync)
        {
            return;
        }

        auto [pos, gocpp_id_0] = rec::Seek(gocpp::recv(r->Data), 0, io::SeekCurrent);
        auto mHave = SyncMarker(rec::rawUvarint(gocpp::recv(r)));
        auto writerPCs = gocpp::make(gocpp::Tag<gocpp::slice<int>>(), rec::rawUvarint(gocpp::recv(r)));
        for(auto [i, gocpp_ignored] : writerPCs)
        {
            writerPCs[i] = int(rec::rawUvarint(gocpp::recv(r)));
        }

        if(mHave == mWant)
        {
            return;
        }

        // There's some tension here between printing:
        // (1) full file paths that tools can recognize (e.g., so emacs
        // hyperlinks the "file:line" text for easy navigation), or
        // (2) short file paths that are easier for humans to read (e.g., by
        // omitting redundant or irrelevant details, so it's easier to
        // focus on the useful bits that remain).
        // The current formatting favors the former, as it seems more
        // helpful in practice. But perhaps the formatting could be improved
        // to better address both concerns. For example, use relative file
        // paths if they would be shorter, or rewrite file paths to contain
        // "$GOROOT" (like objabi.AbsFile does) if tools can be taught how
        // to reliably expand that again.
        mocklib::Printf("export data desync: package %q, section %v, index %v, offset %v\n"_s, r->common->pkgPath, r->k, r->Idx, pos);

        mocklib::Printf("\nfound %v, written at:\n"_s, mHave);
        if(len(writerPCs) == 0)
        {
            mocklib::Printf("\t[stack trace unavailable; recompile package %q with -d=syncframes]\n"_s, r->common->pkgPath);
        }
        for(auto [gocpp_ignored, pc] : writerPCs)
        {
            mocklib::Printf("\t%s\n"_s, rec::StringIdx(gocpp::recv(r->common), rec::rawReloc(gocpp::recv(r), RelocString, pc)));
        }

        mocklib::Printf("\nexpected %v, reading at:\n"_s, mWant);
        // TODO(mdempsky): Dynamically size?
        gocpp::array<uintptr_t, 32> readerPCs = {};
        auto n = runtime::Callers(2, readerPCs.make_slice(0));
        for(auto [gocpp_ignored, pc] : fmtFrames(readerPCs.make_slice(0, n)))
        {
            mocklib::Printf("\t%s\n"_s, pc);
        }

        // We already printed a stack trace for the reader, so now we can
        // simply exit. Printing a second one with panic or base.Fatalf
        // would just be noise.
        os::Exit(1);
    }

    // Bool decodes and returns a bool value from the element bitstream.
    bool rec::Bool(Decoder* r)
    {
        rec::Sync(gocpp::recv(r), SyncBool);
        auto [x, err] = rec::ReadByte(gocpp::recv(r->Data));
        rec::checkErr(gocpp::recv(r), err);
        assert(x < 2);
        return x != 0;
    }

