    // Value decodes and returns a constant.Value from the element
    // bitstream.
    constant::Value rec::Value(Decoder* r)
    {
        rec::Sync(gocpp::recv(r), SyncValue);
        auto isComplex = rec::Bool(gocpp::recv(r));
        auto val = rec::scalar(gocpp::recv(r));
        if(isComplex)
        {
            val = constant::BinaryOp(val, token::ADD, constant::MakeImag(rec::scalar(gocpp::recv(r))));
        }
        return val;
    }

    constant::Value rec::scalar(Decoder* r)
    {
        //Go switch emulation
        {
            auto tag = CodeVal(rec::Code(gocpp::recv(r), SyncVal));
            auto condition = tag;
            int conditionId = -1;
            if(condition == ValBool) { conditionId = 0; }
            else if(condition == ValString) { conditionId = 1; }
            else if(condition == ValInt64) { conditionId = 2; }
            else if(condition == ValBigInt) { conditionId = 3; }
            else if(condition == ValBigRat) { conditionId = 4; }
            else if(condition == ValBigFloat) { conditionId = 5; }
            switch(conditionId)
            {
                default:
                    gocpp::panic(mocklib::Errorf("unexpected scalar tag: %v"_s, tag));
                    break;

                case 0:
                    return constant::MakeBool(rec::Bool(gocpp::recv(r)));
                    break;
                case 1:
                    return constant::MakeString(rec::String(gocpp::recv(r)));
                    break;
                case 2:
                    return constant::MakeInt64(rec::Int64(gocpp::recv(r)));
                    break;
                case 3:
                    return constant::Make(rec::bigInt(gocpp::recv(r)));
                    break;
                case 4:
                {
                    auto num = rec::bigInt(gocpp::recv(r));
                    auto denom = rec::bigInt(gocpp::recv(r));
                    return constant::Make(rec::SetFrac(gocpp::recv(new big::Rat{}), num, denom));
                    break;
                }
                case 5:
                    return constant::Make(rec::bigFloat(gocpp::recv(r)));
                    break;
            }
        }
    }

    big::Int* rec::bigInt(Decoder* r)
    {
        auto v = rec::SetBytes(gocpp::recv(new big::Int{}), gocpp::slice<unsigned char>(rec::String(gocpp::recv(r))));
        if(rec::Bool(gocpp::recv(r)))
        {
            rec::Neg(gocpp::recv(v), v);
        }
        return v;
    }

    big::Float* rec::bigFloat(Decoder* r)
    {
        auto v = rec::SetPrec(gocpp::recv(new big::Float{}), 512);
        assert(rec::UnmarshalText(gocpp::recv(v), gocpp::slice<unsigned char>(rec::String(gocpp::recv(r)))) == nullptr);
        return v;
    }

    // PeekPkgPath returns the package path for the specified package
    // index.
    gocpp::string rec::PeekPkgPath(PkgDecoder* pr, Index idx)
    {
        gocpp::string path = {};
        {
            auto r = rec::TempDecoder(gocpp::recv(pr), RelocPkg, idx, SyncPkgDef);
            path = rec::String(gocpp::recv(r));
            rec::RetireDecoder(gocpp::recv(pr), & r);
        }
        if(path == ""_s)
        {
            path = pr->pkgPath;
        }
        return path;
    }

    // PeekObj returns the package path, object name, and CodeObj for the
    // specified object index.
    std::tuple<gocpp::string, gocpp::string, CodeObj> rec::PeekObj(PkgDecoder* pr, Index idx)
    {
        Index ridx = {};
        gocpp::string name = {};
        int rcode = {};
        {
            auto r = rec::TempDecoder(gocpp::recv(pr), RelocName, idx, SyncObject1);
            rec::Sync(gocpp::recv(r), SyncSym);
            rec::Sync(gocpp::recv(r), SyncPkg);
            ridx = rec::Reloc(gocpp::recv(r), RelocPkg);
            name = rec::String(gocpp::recv(r));
            rcode = rec::Code(gocpp::recv(r), SyncCodeObj);
            rec::RetireDecoder(gocpp::recv(pr), & r);
        }

        auto path = rec::PeekPkgPath(gocpp::recv(pr), ridx);
        assert(name != ""_s);

        auto tag = CodeObj(rcode);

        return {path, name, tag};
    }

